// A fake dev server: prints a banner, emits the runner's render-milestone
// (the same OSC-title protocol as packages/prompts/src/milestone.ts), and
// waits for SIGINT to prove the terminal signal reaches the tool.
process.stdout.write(`fake vitepress argv: ${process.argv.slice(2).join(' ')}\n`);
process.stdout.write('fake vitepress dev server listening\n');
if (process.env.VP_EMIT_MILESTONES === '1') {
  const id = require('node:crypto').randomBytes(16).toString('hex');
  const name = Buffer.from('doc-dev-server:ready').toString('base64url');
  process.stdout.write(`\x1b]2;pty-terminal-test:${id}:${name}\x1b\\`);
}
process.on('SIGINT', () => {
  process.stdout.write('fake vitepress dev: SIGINT received, shutting down\n');
  process.exit(130);
});
setInterval(() => {}, 1000);
